<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase';
import {readFinanceWorkbook,draftSheet,importTotals,monthCandidate,normalizeHeader,type WorkbookPreview,type ImportRow,type SheetMapping} from '@/lib/financeReconciliation';
import {formatPen,penCents,limaDate} from '@/lib/financeMoney';
defineProps<{zones:{id:string;name:string}[]}>();const emit=defineEmits<{changed:[]}>();
type Candidate={id:string;contract_number:string;client_code:string;customer:string;monthly_fee:string;status:string;service_type:string};
type Invoice={id:string;invoice_number:string;amount:string;amount_due:string;period_start:string;period_end:string;finance_reconciled:boolean;finance_origin:string};
type Compared={key:string;candidateCount:number;candidates:Candidate[];invoices:Invoice[];possiblePayments:{id:string;amount:string;method:string;reference:string;reversed_at:string|null}[]};
const file=ref<WorkbookPreview|null>(null),sheetIndex=ref(0),error=ref(''),notice=ref(''),busy=ref(false),rows=ref<ImportRow[]>([]),warnings=ref<Record<string,string>>({}),compared=ref<Record<string,Compared>>({}),page=ref(1),year=ref(''),confirmedMapping=ref(false);
const context=ref<{canApply:boolean;collectors:{id:string;name:string}[]}|null>(null),startedOn=ref(''),label=ref('Conciliación de Google Sheets'),batchReason=ref(''),originalCollector=ref(''),batchId=ref(''),reviewOpen=ref(false),outcome=ref<Record<string,unknown>|null>(null);
const mapping=ref<SheetMapping>({zoneId:'',contract:'',subscriber:'',customer:'',fee:'',date:'',method:'',reference:'',months:{},mode:'matrix',amountColumn:'',periodColumn:''}),monthColumns=ref<string[]>([]);
const kinds:Record<string,string>={payment:'Pago recibido',advance:'Anticipo recibido',discount:'Descuento',exemption:'Exoneración',promotion:'Promoción 3+1',opening_debt:'Deuda inicial verificada',opening_credit:'Saldo a favor inicial',link:'Vincular pago existente'};
const sheet=computed(()=>file.value?.sheets[sheetIndex.value]),visible=computed(()=>rows.value.slice((page.value-1)*50,page.value*50));
const sourceCell=(row:ImportRow)=>file.value?.sheets.find(s=>s.name===row.sheet)?.rows.find(r=>r.number===row.row)?.cells[row.column]?.value??'';
const reviewedBatch=ref('');
function duplicateOf(row:ImportRow){if(!['payment','advance','promotion'].includes(row.kind)||!row.amount||!row.receivedOn)return false;const signature=(r:ImportRow)=>JSON.stringify([r.zoneId,r.contractId||r.contractCode||r.subscriber,r.amount,r.receivedOn,r.method,r.reference.trim().toLowerCase()]);return rows.value.find(r=>['payment','advance','promotion'].includes(r.kind)&&signature(r)===signature(row))?.key!==row.key;}
async function rpc<T>(name:string,args:Record<string,unknown>={}){const r=await supabase.rpc(name,args);if(r.error)throw Error(r.error.message);return r.data as T;}
onMounted(async()=>{try{context.value=await rpc('finance_import_context');}catch(e){error.value=String(e);}});
function configure(){const headers=sheet.value?.headers??[],find=(re:RegExp)=>headers.find(h=>re.test(normalizeHeader(h.label)))?.column??'';mapping.value={...mapping.value,contract:find(/^contrato|codigo.*contrato/),subscriber:find(/cintillo|codigo.*abonado/),customer:find(/^cliente|^nombre/),fee:find(/mensualidad|tarifa/),date:find(/fecha.*pago|fecha.*cobro/),method:find(/metodo|^medio$|medio.*pago/),reference:find(/operacion|referencia/),observation:find(/observaci|anotaci|nota/),amountColumn:find(/^importe|^monto/),periodColumn:find(/^periodo/)};monthColumns.value=headers.filter(h=>monthCandidate(h.label)).map(h=>h.column);confirmedMapping.value=false;}
async function upload(event:Event){const selected=(event.target as HTMLInputElement).files?.[0];if(!selected)return;busy.value=true;error.value='';try{if(!/\.xlsx$/i.test(selected.name))throw Error('Exporta desde Sheets como Excel .xlsx, sin macros.');file.value=await readFinanceWorkbook(await selected.arrayBuffer());sheetIndex.value=0;rows.value=[];compared.value={};outcome.value=null;configure();}catch(e){error.value=String(e);}finally{busy.value=false;}}
function addSheet(){error.value='';try{if(!sheet.value||!mapping.value.zoneId||!confirmedMapping.value)throw Error('Selecciona PON y confirma el significado financiero de las columnas.');if(mapping.value.mode==='matrix'){if(!/^\d{4}$/.test(year.value)||Number(year.value)<2020||Number(year.value)>2100||!monthColumns.value.length)throw Error('Indica año real de la fuente y mensualidades a revisar.');mapping.value.months=Object.fromEntries(monthColumns.value.map(column=>{const h=sheet.value!.headers.find(h=>h.column===column)!;const stated=/\b(\d{4})\b/.exec(h.label)?.[1];if(stated&&stated!==year.value)throw Error('El año del encabezado no coincide con el año elegido.');return[column,`${year.value}-${String(monthCandidate(h.label)).padStart(2,'0')}`];}));}else if(!mapping.value.amountColumn)throw Error('Selecciona la columna de importe.');const draft=draftSheet(sheet.value,mapping.value);for(const r of draft.rows)r.method=method(r.method);const existing=new Set(rows.value.map(r=>r.key));const added=draft.rows.filter(r=>!existing.has(r.key));if(rows.value.length+added.length>5000)throw Error('Procesa por PON: máximo 5000 registros en esta sesión.');rows.value.push(...added);warnings.value={...warnings.value,...draft.warnings};page.value=1;notice.value=`${draft.rows.length} celdas no vacías de la hoja; vacíos ignorados. Nada importado.`;}catch(e){error.value=String(e);}}
function invalidate(row:ImportRow){delete compared.value[row.key];row.reviewed=false;batchId.value='';reviewOpen.value=false;}
async function compare(){if(busy.value||!visible.value.length)return;busy.value=true;error.value='';try{const data=await rpc<{rows:Compared[]}>('finance_import_preview',{p_rows:visible.value});for(const r of data.rows)compared.value[r.key]=r;notice.value='Comparación de solo lectura. Selecciona el contrato exacto y verifica cargos, fechas y evidencia.';}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function resolveExact(){for(const r of visible.value){const c=compared.value[r.key];if(c?.candidateCount!==1)continue;const target=c.candidates[0]!;if((r.contractCode||r.subscriber)&&(!r.contractCode||r.contractCode===target.contract_number)&&(!r.subscriber||r.subscriber===target.client_code)){r.contractId=target.id;r.reviewed=false;}}await compare();for(const r of visible.value){const data=compared.value[r.key];if(r.contractId&&data?.candidateCount===1&&data.invoices.length===1&&['payment','discount','exemption'].includes(r.kind)){r.invoiceId=data.invoices[0]!.id;r.expectedDue=String(data.invoices[0]!.amount_due);}}}
function match(row:ImportRow,id:string){row.contractId=id;row.invoiceId='';row.invoiceIds=[];row.expectedDue='';invalidate(row);}
function invoice(row:ImportRow,id:string){row.invoiceId=id;const i=compared.value[row.key]?.invoices.find(i=>i.id===id);row.expectedDue=i?String(i.amount_due):'';row.reviewed=false;batchId.value='';}
function method(value:string){const aliases:Record<string,string>={efectivo:'cash',cash:'cash',yape:'yape',plin:'plin',transferencia:'transfer',transfer:'transfer',otros:'other',other:'other'};return aliases[normalizeHeader(value)]??value;}
function issues(row:ImportRow):string[]{const out:string[]=[],c=compared.value[row.key];if(duplicateOf(row))out.push('Posible duplicado dentro del archivo: resolver antes de importar');if(!row.contractId)out.push('Seleccionar contrato exacto');if(!c||!c.candidates.some(c=>c.id===row.contractId))out.push('Comparar la selección con SmartRayco');try{if(penCents(row.amount)<=0)out.push('Importe real requerido');}catch{out.push('Importe ambiguo');}if(['payment','advance','promotion','link'].includes(row.kind)){if(!/^\d{4}-\d{2}-\d{2}$/.test(row.receivedOn)||row.receivedOn>limaDate())out.push('Fecha real del cobro requerida');if(!['cash','yape','plin','transfer','other'].includes(method(row.method)))out.push('Método no identificado');if(!row.collectorId)out.push('Cobrador original no identificado');if(row.method!=='cash'&&!row.reference.trim())out.push('Referencia digital requerida');if(c?.possiblePayments.length&&row.kind!=='link')out.push('Posible pago existente: revisar vínculo o reverso');}if(['payment','discount','exemption'].includes(row.kind)){const inv=c?.invoices.find(i=>i.id===row.invoiceId);if(!inv)out.push('Seleccionar factura');else if(row.fee&&inv.finance_origin==='operational'&&penCents(row.fee)!==penCents(inv.amount))out.push('Mensualidad fuente difiere del cargo');}if(row.kind==='promotion'&&row.invoiceIds.length!==4)out.push('Seleccionar cuatro facturas futuras verificadas');if(row.kind==='link'&&!row.paymentId)out.push('Seleccionar movimiento existente vigente');if(row.kind.startsWith('opening_')&&(!row.asOf||row.asOf!==startedOn.value))out.push('Fecha de apertura debe coincidir con inicio aprobado');if(row.kind==='opening_debt'&&(!row.periodStart||!row.periodEnd||!row.dueOn))out.push('Cobertura y vencimiento verificables requeridos');if(row.reason.trim().length<10)out.push('Motivo/evidencia de revisión requerido');if(!row.reviewed)out.push('Sin confirmación humana');return out;}
const ready=computed(()=>visible.value.filter(r=>!issues(r).length)),counts=computed(()=>({valid:ready.value.length,pending:visible.value.length-ready.value.length}));
function applyCollector(){if(!originalCollector.value)return;for(const r of visible.value)if(['payment','advance','promotion','link'].includes(r.kind)){r.collectorId=originalCollector.value;r.reviewed=false;}batchId.value='';}
function review(){error.value='';try{if(!context.value?.canApply)throw Error('Ejecución cerrada fuera del laboratorio sintético.');if(!startedOn.value||startedOn.value>limaDate()||batchReason.value.trim().length<10||!ready.value.length)throw Error('Confirma fecha financiera, motivo de lote y al menos un registro válido.');for(const r of ready.value)r.method=method(r.method);batchId.value=crypto.randomUUID();reviewedBatch.value=JSON.stringify([ready.value,startedOn.value,label.value,batchReason.value]);reviewOpen.value=true;}catch(e){error.value=String(e);}}
async function commit(){if(busy.value||!reviewOpen.value)return;busy.value=true;error.value='';try{if(reviewedBatch.value!==JSON.stringify([ready.value,startedOn.value,label.value,batchReason.value])){reviewOpen.value=false;throw Error('La vista revisada cambi\u00f3. Revisa el lote nuevamente.');}const accepted=ready.value;const result=await rpc<Record<string,unknown>>('finance_import_commit',{p_batch_id:batchId.value,p_label:label.value,p_started_on:startedOn.value,p_rows:accepted,p_reason:batchReason.value,p_expected_totals:importTotals(accepted)});outcome.value=result;reviewOpen.value=false;notice.value='Lote confirmado en laboratorio; revisa totales aplicados y registros ya existentes. No hubo operaciones de red.';emit('changed');}catch(e){error.value=String(e);}finally{busy.value=false;}}
function exportReview(){const safe=(v:unknown)=>'"'+String(v??'').replace(/^\s*[=+@-]/,"'").replaceAll('"','""')+'"';const data=[['Hoja','Fila','Columna','Cintillo','Contrato fuente','Tipo','Periodo','Importe fuente','Importe revisado','Estado / diferencias'],...rows.value.map(r=>[r.sheet,r.row,r.column,r.subscriber,r.contractCode,kinds[r.kind],r.period,r.sourceAmount,r.amount,issues(r).join(' / ')||'Verificado'])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='conciliacion-vista-previa.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section class="finance-reconciliation"><header class="finance-table-tools"><h2>Conciliación desde Google Sheets</h2><button class="btn-ghost" :disabled="!rows.length" @click="exportReview">Exportar revisión (CSV)</button></header><p class="finance-warning"><b>Sin habilitación productiva</b><span>Archivos procesados en memoria. No se sube Excel ni se activan cortes. La muestra real sigue pendiente de validación.</span></p><p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="notice" role="status" class="finance-notice">{{notice}}</p>
 <article class="finance-panel"><h3>1. Archivo y hojas por PON</h3><label class="reconcile-upload">Excel exportado desde Google Sheets<input type="file" accept=".xlsx" :disabled="busy" aria-label="Archivo Excel de conciliación" @change="upload"></label><template v-if="file"><p>{{file.sheets.length}} hojas · {{file.excludedColumns}} columnas técnicas excluidas · {{file.blankCells}} celdas vacías, sin interpretación de deuda.</p><div class="finance-filters"><label>Hoja<select v-model.number="sheetIndex" aria-label="Hoja de conciliación" @change="configure"><option v-for="(s,n) in file.sheets" :key="s.name" :value="n">{{s.name}}</option></select></label><label>PON verificada<select v-model="mapping.zoneId" aria-label="PON de conciliación"><option value="">Seleccionar relación real</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}}</option></select></label><label>Organización<select v-model="mapping.mode"><option value="matrix">Mensualidades en columnas</option><option value="ledger">Operaciones en filas</option></select></label><label v-if="mapping.mode==='matrix'">Año real de la hoja<input v-model="year" type="number" min="2020" max="2100" aria-label="Año del Excel"></label></div>
 <div class="reconcile-mapping"><label v-for="[key,title] in [['contract','Contrato'],['subscriber','Cintillo / abonado'],['customer','Cliente'],['fee','Mensualidad fuente'],['date','Fecha real del cobro'],['method','Medio de pago'],['observation','Observaciones locales'],['reference','Operación / recibo fuente']]" :key="key">{{title}}<select v-model="(mapping as unknown as Record<string,unknown>)[key!]"><option value="">No disponible</option><option v-for="h in sheet?.headers" :key="h.column" :value="h.column">{{h.column}} · {{h.label}}</option></select></label></div>
 <div v-if="mapping.mode==='matrix'" class="reconcile-months"><label v-for="h in sheet?.headers.filter(h=>monthCandidate(h.label))" :key="h.column"><input v-model="monthColumns" type="checkbox" :value="h.column">{{h.label}}</label></div><div v-else class="finance-filters"><label>Importe<select v-model="mapping.amountColumn"><option value="">Seleccionar</option><option v-for="h in sheet?.headers" :key="h.column" :value="h.column">{{h.label}}</option></select></label><label>Período de servicio (AAAA-MM)<select v-model="mapping.periodColumn"><option value="">Sin asignación</option><option v-for="h in sheet?.headers" :key="h.column" :value="h.column">{{h.label}}</option></select></label></div>
 <label class="reconcile-attest"><input v-model="confirmedMapping" type="checkbox">Verifiqué qué representan las columnas elegidas. No trataré colores ni vacíos como pagos o deuda; cada operación se revisará antes de confirmar.</label><button class="btn-secondary" :disabled="busy" @click="addSheet">Añadir hoja a vista previa</button></template></article>
 <template v-if="rows.length"><article class="finance-panel"><h3>2. Identificar y revisar operaciones</h3><div class="finance-filters"><label>Responsable original confirmado<select v-model="originalCollector" aria-label="Cobrador original"><option value="">Sin identificar</option><option v-for="c in context?.collectors" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="btn-ghost" @click="applyCollector">Aplicar responsable a esta página</button><button class="btn-secondary" :disabled="busy" @click="compare">Comparar página con SmartRayco</button><button class="btn-ghost" :disabled="busy" @click="resolveExact">Resolver coincidencias exactas</button></div><p class="finance-help">Solo coincidencias verificables. Un nombre igual no autoriza elegir el primer contrato. Las mensualidades diferentes requieren resolver el cargo histórico; no se cambia el plan ni la tarifa automáticamente.</p><div class="reconcile-rows"><details v-for="r in visible" :key="r.key" class="reconcile-row"><summary class="reconcile-row-head"><b>{{r.sheet}} · {{r.row}}:{{r.column}}</b><span>{{r.customer}} · {{r.subscriber||r.contractCode||'Sin identificador'}}</span><span>{{r.period||'Período sin identificar'}}</span></summary><p class="finance-help">Celda fuente (solo local): {{sourceCell(r)}} / Importe fuente verificable: {{r.sourceAmount||'No identificado'}}.</p><p v-if="warnings[r.key]" class="reconcile-hint">{{warnings[r.key]}}</p><div class="reconcile-row-fields"><label>Operación<select v-model="r.kind" @change="invalidate(r)"><option v-for="(title,key) in kinds" :key="key" :value="key">{{title}}</option></select></label><label>Importe real PEN<input v-model="r.amount" inputmode="decimal" @change="invalidate(r)"></label><label>Código contrato fuente<input v-model="r.contractCode" @change="r.contractId='';invalidate(r)"></label><label>Contrato exacto<select :value="r.contractId" @change="match(r,($event.target as HTMLSelectElement).value)"><option value="">Seleccionar / comparar</option><option v-for="c in compared[r.key]?.candidates" :key="c.id" :value="c.id">{{c.contract_number}} · {{c.client_code}} · {{c.customer}} · {{c.service_type}}</option></select></label></div>
 <div class="reconcile-row-fields" v-if="['payment','advance','promotion','link'].includes(r.kind)"><label>Fecha real (sin inventar hora)<input v-model="r.receivedOn" type="date" @change="r.reviewed=false"></label><label>Método<select v-model="r.method" @change="r.reviewed=false"><option value="">Sin identificar</option><option value="cash">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="transfer">Transferencia</option><option value="other">Otros</option></select></label><label>Operación / recibo de origen<input v-model="r.reference" maxlength="100" @change="r.reviewed=false"></label><label>Responsable original<select v-model="r.collectorId" @change="r.reviewed=false"><option value="">Sin identificar</option><option v-for="c in context?.collectors" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div>
 <div v-if="['payment','discount','exemption'].includes(r.kind)" class="reconcile-invoice"><label>Factura / saldo verificado<select :value="r.invoiceId" @change="invoice(r,($event.target as HTMLSelectElement).value)"><option value="">Seleccionar después de comparar</option><option v-for="i in compared[r.key]?.invoices" :key="i.id" :value="i.id">{{i.invoice_number}} · {{i.period_start}} · saldo {{formatPen(i.amount_due)}} · {{i.finance_reconciled?'Conciliada':'Histórica no conciliada'}}</option></select></label><span>Mensualidad en fuente: {{r.fee?formatPen(r.fee):'No indicada'}}. No se reemplaza el importe recibido por la mensualidad.</span></div>
 <div v-if="r.kind==='promotion'" class="reconcile-promo"><p>Cuatro facturas futuras según regla 3+1 vigente. El importe debe proceder de la evidencia; no se calcula como supuesto pago.</p><label v-for="i in compared[r.key]?.invoices" :key="i.id"><input v-model="r.invoiceIds" type="checkbox" :value="i.id" @change="r.reviewed=false">{{i.period_start}} · {{formatPen(i.amount)}}</label></div>
 <div v-if="r.kind==='link'"><label>Movimiento existente vigente<select v-model="r.paymentId" @change="r.reviewed=false"><option value="">Seleccionar</option><option v-for="p in compared[r.key]?.possiblePayments.filter(p=>!p.reversed_at)" :key="p.id" :value="p.id">{{formatPen(p.amount)}} · {{p.method}} · {{p.reference}}</option></select></label></div>
 <div v-if="r.kind.startsWith('opening_')" class="reconcile-row-fields"><label>Corte verificado<input v-model="r.asOf" type="date" @change="r.reviewed=false"></label><template v-if="r.kind==='opening_debt'"><label>Cobertura desde<input v-model="r.periodStart" type="date" @change="r.reviewed=false"></label><label>Cobertura hasta<input v-model="r.periodEnd" type="date" @change="r.reviewed=false"></label><label>Vencimiento de la deuda<input v-model="r.dueOn" type="date" @change="r.reviewed=false"></label></template><p>No representa dinero recibido en este período. No se borran los registros históricos.</p></div>
 <label class="reconcile-reason">Motivo / evidencia financiera revisada<input v-model="r.reason" maxlength="500" minlength="10" placeholder="Describe la verificación sin credenciales ni datos técnicos" @change="r.reviewed=false"></label><label class="reconcile-attest"><input v-model="r.reviewed" type="checkbox">Confirmé identidad, importe, fecha y respaldo de esta operación.</label><small :class="issues(r).length?'reconcile-pending':'reconcile-valid'">{{issues(r).join(' · ')||'Verificado para revisión final del lote'}}</small></details></div><div class="finance-pagination"><span>{{rows.length}} registros · {{counts.valid}} verificados / {{counts.pending}} pendientes en página {{page}}</span><button :disabled="page===1||busy" @click="page--">Anterior</button><button :disabled="page*50>=rows.length||busy" @click="page++">Siguiente</button></div></article>
 <article class="finance-panel"><h3>3. Inicio financiero y revisión final</h3><div class="finance-filters"><label>Nombre del lote<input v-model="label" maxlength="120"></label><label>Fecha oficial aprobada<input v-model="startedOn" type="date"></label><label>Motivo del lote<input v-model="batchReason" maxlength="500" minlength="10"></label></div><p>La fecha no está impuesta. Se confirmará después de validar una muestra real. No habilita cortes ni reconexiones.</p><p v-if="!context?.canApply" class="finance-warning">Ejecución productiva bloqueada. La vista previa y el reporte funcionan sin importar datos reales.</p><button class="btn-primary" :disabled="busy||!context?.canApply||!ready.length" @click="review">Revisar lote de laboratorio</button><div v-if="reviewOpen" class="reconcile-final"><h3>Confirmación humana · {{ready.length}} operaciones</h3><p>Dinero fuente {{formatPen(importTotals(ready).cash)}} · deuda inicial {{formatPen(importTotals(ready).debt)}} · crédito inicial {{formatPen(importTotals(ready).credit)}} · descuentos {{formatPen(importTotals(ready).discount)}} · vinculados {{formatPen(importTotals(ready).linked)}}</p><p>Transacción de hasta 50 operaciones. Los pagos ya importados no vuelven a generar caja. No se sube el Excel.</p><button class="btn-secondary" :disabled="busy" @click="reviewOpen=false">Volver a revisión</button><button class="btn-primary" :disabled="busy" @click="commit">Confirmar importación sintética</button></div><div v-if="outcome" class="reconcile-result"><h3>Resultado del lote</h3><pre>{{JSON.stringify(outcome,null,2)}}</pre><p>Importes fuente y aplicados se conservan separados. No se contabilizan descuentos o aperturas como recaudación.</p></div></article></template>
 </section></template>
<style scoped>
.finance-reconciliation{min-width:0;overflow-wrap:anywhere}.finance-reconciliation .finance-panel,.reconcile-rows,.reconcile-row,.reconcile-row-fields>*,.reconcile-invoice>*{min-width:0}.finance-reconciliation input[type=file],.finance-reconciliation select{max-width:100%}.reconcile-row-head{cursor:pointer}.finance-reconciliation .finance-pagination{flex-wrap:wrap}.finance-reconciliation .finance-filters>label{max-width:100%}.finance-reconciliation .finance-filters input{max-width:100%}
